+    void warm_phase() {
+        // Software mirror of struct idma_stream::in_flight: at most one
+        // transfer outstanding per channel.
+        bool     v_in_flight = false, a_in_flight = false;
+        uint64_t v_id = 0, a_id = 0;
+        long     drain_start;
+        long     a_deadline;
+
+        warm_start_cycle      = g_cycle;
+        warm_v_progress_cycle = g_cycle;
+        warm_a_page           = 0;
+        warm_v_submitted      = 0;
+        warm_v_completed      = 0;
+        warm_a_submitted      = 0;
+        warm_a_completed      = 0;
+        warm_overlap_ticks    = 0;
+        warm_a_drained        = false;
+        warm_a_drain_cycles   = 0;
+        warm_hw_track         = false;   // enabled below only if warmup > 0
+        warm_hw_v_busy        = false;
+        warm_hw_a_busy        = false;
+        warm_hw_v_issue       = 0;
+        warm_hw_v_done        = 0;
+        warm_hw_a_issue       = 0;
+        warm_hw_a_done        = 0;
